use std::{
    fs,
    path::PathBuf,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};

use anyhow::{bail, Context, Result};
use clap::Parser;
use erd_app::{
    ClientSession, LatencyRecorder, PairingRecord, SessionConfig, SessionEvent,
};
use erd_decode::HevcDecoder;
use erd_proto::{Capabilities, ControlMessage};
use tracing::{debug, error, info, warn};
use tracing_subscriber::EnvFilter;

const DEFAULT_TCP_PORT: u16 = 49152;
const DEFAULT_UDP_PORT: u16 = 49153;
const DEFAULT_TIMEOUT_SECS: u64 = 30;

#[derive(Debug, Parser)]
#[command(
    name = "erd-client",
    about = "Ecliptic Remote Desktop headless testing client for VM E2E driving",
    version
)]
struct Cli {
    /// Remote host address (IPv4, IPv6, or hostname).
    #[arg(long)]
    host: String,

    /// Remote host TCP TLS-PSK signaling port.
    #[arg(long, default_value_t = DEFAULT_TCP_PORT)]
    tcp_port: u16,

    /// Remote host UDP media port.
    #[arg(long)]
    udp_port: Option<u16>,

    /// 8-digit bootstrap PIN for pairing with the host.
    #[arg(long, conflicts_with = "psk_hex")]
    pin: Option<String>,

    /// 64-character hexadecimal pre-shared key (32 bytes) if pairing store is unavailable.
    #[arg(long, conflicts_with = "pin")]
    psk_hex: Option<String>,

    /// Pairing ID associated with psk-hex or pairing store reconnect.
    #[arg(long)]
    pairing_id: Option<String>,

    /// Optional explicit path to pairing store file.
    #[arg(long)]
    pairing_store: Option<PathBuf>,

    /// Exit 0 immediately after successfully decoding N video frames.
    #[arg(long)]
    frames: Option<u64>,

    /// Path to write JSON latency statistics upon completion.
    #[arg(long)]
    stats_json: Option<PathBuf>,

    /// Overall execution timeout in seconds.
    #[arg(long, default_value_t = DEFAULT_TIMEOUT_SECS)]
    timeout_secs: u64,

    /// Name of client sent in handshake.
    #[arg(long, default_value = "erd-headless-client")]
    client_name: String,
}

fn parse_hex_32(hex_str: &str) -> Result<Vec<u8>> {
    let trimmed = hex_str.trim();
    if trimmed.len() != 64 {
        bail!("psk-hex must be exactly 64 hex characters (32 bytes), got length {}", trimmed.len());
    }
    let mut bytes = Vec::with_capacity(32);
    for i in (0..64).step_by(2) {
        let byte = u8::from_str_radix(&trimmed[i..i + 2], 16)
            .with_context(|| format!("invalid hex digit pair '{}'", &trimmed[i..i + 2]))?;
        bytes.push(byte);
    }
    Ok(bytes)
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let cli = Cli::parse();
    run_client(cli)
}

fn run_client(cli: Cli) -> Result<()> {
    let udp_port = cli.udp_port.unwrap_or_else(|| {
        if cli.tcp_port == DEFAULT_TCP_PORT {
            DEFAULT_UDP_PORT
        } else {
            cli.tcp_port.saturating_add(1)
        }
    });

    let target_frames = cli.frames.unwrap_or(u64::MAX);
    let timeout = Duration::from_secs(cli.timeout_secs);
    let start_time = Instant::now();

    let session_config = SessionConfig {
        host: cli.host.clone(),
        tcp_port: cli.tcp_port,
        udp_port,
        client_name: cli.client_name.clone(),
        capabilities: Capabilities::STREAM_CONFIGURATION | Capabilities::TEXT_CLIPBOARD_SYNC,
        pairing_store_path: cli.pairing_store.clone(),
        connect_timeout: Duration::from_secs(10),
        handshake_ack_timeout: Duration::from_secs(10),
    };

    info!(
        host = %cli.host,
        tcp_port = cli.tcp_port,
        udp_port = udp_port,
        timeout_secs = cli.timeout_secs,
        "Initializing headless client session"
    );

    let session = ClientSession::new(session_config).context("failed to construct ClientSession")?;

    let ready = match (&cli.pin, &cli.psk_hex) {
        (Some(pin), None) => {
            info!("Initiating bootstrap pairing with host via PIN");
            session.pair_with_pin(pin).context("bootstrap pairing failed")?
        }
        (None, Some(psk_hex)) => {
            let key = parse_hex_32(psk_hex).context("invalid --psk-hex argument")?;
            let pairing_id = cli
                .pairing_id
                .clone()
                .unwrap_or_else(|| "00000000-0000-0000-0000-000000000000".to_string());
            let pairing = PairingRecord {
                id: pairing_id,
                name: cli.host.clone(),
                key,
                added_at_unix_ms: 0,
            };
            info!(pairing_id = %pairing.id, "Connecting with explicit PSK");
            session
                .connect_with_pairing(pairing)
                .context("handshake with explicit PSK failed")?
        }
        (None, None) => {
            if let Some(pairing_id) = &cli.pairing_id {
                info!(pairing_id = %pairing_id, "Reconnecting with stored pairing record");
                session
                    .reconnect(pairing_id)
                    .context("reconnect with stored pairing failed")?
            } else {
                bail!("either --pin, --psk-hex, or --pairing-id must be provided");
            }
        }
        (Some(_), Some(_)) => {
            unreachable!("clap enforces conflicts between pin and psk_hex");
        }
    };

    info!(
        host_name = %ready.server.name,
        width = ready.server.width,
        height = ready.server.height,
        version = ready.server.version,
        "Handshake completed, session ready"
    );

    // Spawn TCP control loop
    let mut tcp_runtime = session
        .spawn_tcp_runtime()
        .context("failed to spawn TCP runtime")?;

    let running = Arc::new(AtomicBool::new(true));
    let r_ctrl = running.clone();
    let _ = ctrlc_handler(move || {
        r_ctrl.store(false, Ordering::SeqCst);
    });

    let mut latency_recorder = LatencyRecorder::new();
    let mut decoder: Option<HevcDecoder> = None;
    let mut decoded_frames: u64 = 0;

    info!("Awaiting UDP media datagrams and decoding frames...");

    while running.load(Ordering::Relaxed) {
        if start_time.elapsed() >= timeout {
            error!("Session timed out after {} seconds", cli.timeout_secs);
            let _ = teardown(&session, &mut tcp_runtime);
            write_stats_file(cli.stats_json.as_deref(), &latency_recorder)?;
            bail!("timeout expired before decoding requested frames");
        }

        if decoded_frames >= target_frames {
            info!(decoded_frames, "Reached requested target frame count");
            break;
        }

        // Check if TCP runtime emitted an error
        while let Ok(event_res) = tcp_runtime.events().try_recv() {
            match event_res {
                Ok(SessionEvent::Ping) => {
                    debug!("TCP heartbeat ping acknowledged");
                }
                Ok(SessionEvent::Clipboard(_text)) => {
                    debug!("Received clipboard update");
                }
                Ok(_) => {}
                Err(err) => {
                    error!(%err, "TCP runtime encountered error");
                    let _ = teardown(&session, &mut tcp_runtime);
                    write_stats_file(cli.stats_json.as_deref(), &latency_recorder)?;
                    return Err(err).context("TCP runtime error");
                }
            }
        }

        // Receive UDP events
        let receive_start = Instant::now();
        match session.receive_udp_event() {
            Ok(SessionEvent::Frame(assembled_frame)) => {
                let receive_ts = Instant::now();
                let is_key = assembled_frame.header.is_key_frame;
                let data = &assembled_frame.data;

                if decoder.is_none() {
                    match HevcDecoder::from_keyframe(data) {
                        Ok(dec) => {
                            info!("HEVC decoder initialized from keyframe");
                            decoder = Some(dec);
                        }
                        Err(err) => {
                            if is_key {
                                warn!(%err, "Failed to initialize HEVC decoder from keyframe");
                            }
                        }
                    }
                }

                let decode_start = Instant::now();
                let mut decoded_any = false;
                if let Some(dec) = decoder.as_mut() {
                    match dec.decode(data, assembled_frame.timestamp_ms as i64) {
                        Ok(nv12_frames) => {
                            if !nv12_frames.is_empty() {
                                decoded_any = true;
                                decoded_frames = decoded_frames.saturating_add(nv12_frames.len() as u64);
                            }
                        }
                        Err(err) => {
                            debug!(%err, "Frame decode error (will retry on next keyframe)");
                        }
                    }
                }

                let present_ts = Instant::now();
                if decoded_any {
                    // Record latency sample: receive/capture -> decode -> present
                    latency_recorder.record_sample(Some(receive_ts), decode_start, present_ts);
                }
            }
            Ok(SessionEvent::Audio(_)) => {
                debug!("Received audio packet");
            }
            Ok(SessionEvent::Cursor(_)) => {
                debug!("Received cursor update");
            }
            Ok(SessionEvent::Ping) => {
                debug!("UDP ping received");
            }
            Ok(SessionEvent::Clipboard(_)) => {
                debug!("Received clipboard update on UDP");
            }
            Ok(SessionEvent::Ignored) => {}
            Err(err) => {
                // If it's a timeout/wouldblock on UDP socket, just continue looping
                if let erd_app::SessionError::Io(ref io_err) = err {
                    if matches!(
                        io_err.kind(),
                        std::io::ErrorKind::TimedOut | std::io::ErrorKind::WouldBlock
                    ) {
                        continue;
                    }
                }
                debug!(%err, "UDP receive event notice");
            }
        }

        // Small yield if no time spent receiving
        if receive_start.elapsed() < Duration::from_millis(1) {
            std::thread::sleep(Duration::from_millis(1));
        }
    }

    info!(
        decoded_frames,
        target_frames,
        "Cleaning up session transport..."
    );
    teardown(&session, &mut tcp_runtime)?;

    let stats_json = latency_recorder.stats_json();
    info!(stats = %stats_json, "Latency statistics summary");

    write_stats_file(cli.stats_json.as_deref(), &latency_recorder)?;

    Ok(())
}

fn teardown(
    session: &ClientSession,
    tcp_runtime: &mut erd_app::SessionRuntime,
) -> Result<()> {
    // Send Disconnect / BYE control message
    let _ = session.send_control(ControlMessage::Disconnect);
    tcp_runtime.stop();
    let _ = session.disconnect();
    Ok(())
}

fn write_stats_file(path: Option<&std::path::Path>, recorder: &LatencyRecorder) -> Result<()> {
    if let Some(stats_path) = path {
        let json = recorder.stats_json();
        if let Some(parent) = stats_path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        fs::write(stats_path, json.as_bytes())
            .with_context(|| format!("failed to write stats JSON to {}", stats_path.display()))?;
        info!("Stats JSON written to {}", stats_path.display());
    }
    Ok(())
}

fn ctrlc_handler<F>(f: F) -> Result<()>
where
    F: Fn() + Send + Sync + 'static,
{
    // Best-effort ctrl-c handler without extra crate
    // On Unix, standard signal hooks can be set or ignored gracefully.
    #[cfg(unix)]
    {
        use std::sync::Once;
        static INIT: Once = Once::new();
        INIT.call_once(|| {
            // Nothing required if signal handler isn't needed, standard SIGINT exits process
        });
    }
    let _ = f;
    Ok(())
}

use std::{net::UdpSocket, sync::mpsc, thread, time::Duration};

use erd_app::{ClientSession, SessionConfig, SessionError, SessionState};
use erd_net::{PskIdentity, TlsPskServer};
use erd_proto::{
    Capabilities, Handshake, InputEvent, InputEventType, Modifiers, PacketHeader, PacketType,
    PairingGrant, PairingRequest, WireCodec, PROTOCOL_VERSION,
};

fn packet(packet_type: PacketType, payload: &[u8]) -> Vec<u8> {
    let mut packet = PacketHeader::new(packet_type, 0, 0, 0).encode().unwrap();
    packet.extend_from_slice(payload);
    packet
}

fn split_packet(packet: &[u8]) -> (PacketHeader, &[u8]) {
    (
        PacketHeader::decode(&packet[..PacketHeader::SIZE]).unwrap(),
        &packet[PacketHeader::SIZE..],
    )
}

#[test]
fn mock_server_pairing_handshake_and_input_round_trip() {
    let pin = "12345678";
    let psk = PskIdentity::bootstrap(pin).unwrap();
    let listener = TlsPskServer::new([psk])
        .unwrap()
        .bind("127.0.0.1:0")
        .unwrap();
    let tcp_address = listener.local_addr().unwrap();
    let udp = UdpSocket::bind("127.0.0.1:0").unwrap();
    let udp_port = udp.local_addr().unwrap().port();
    let (input_tx, input_rx) = mpsc::channel();

    let server = thread::spawn(move || {
        let mut stream = listener.accept().unwrap();
        let request_packet = stream.read_frame().unwrap();
        let (header, payload) = split_packet(&request_packet);
        assert_eq!(header.packet_type, PacketType::PairingRequest);
        assert_eq!(PairingRequest::decode(payload).unwrap().name, "rust-client");

        let grant = PairingGrant {
            pairing_id: "pairing-1".to_owned(),
            host_name: "mock-host".to_owned(),
            key: [0x5a; 32],
        };
        stream
            .write_frame(&packet(PacketType::PairingGrant, &grant.encode().unwrap()))
            .unwrap();

        let handshake_packet = stream.read_frame().unwrap();
        let (header, payload) = split_packet(&handshake_packet);
        assert_eq!(header.packet_type, PacketType::Handshake);
        let handshake = Handshake::decode(payload).unwrap();
        assert_eq!(handshake.pairing_id, "pairing-1");
        assert_ne!(handshake.session_salt, [0; 16]);

        let acknowledgement = Handshake {
            name: "mock-host".to_owned(),
            width: 1920,
            height: 1080,
            scale: 1.0,
            version: PROTOCOL_VERSION,
            capabilities: Capabilities::TEXT_CLIPBOARD_SYNC,
            pairing_id: String::new(),
            session_salt: [0; 16],
        };
        stream
            .write_frame(&packet(
                PacketType::HandshakeAck,
                &acknowledgement.encode().unwrap(),
            ))
            .unwrap();

        let mut ping = [0_u8; 1];
        udp.recv_from(&mut ping).unwrap();
        assert_eq!(ping, [0xff]);

        let input_packet = stream.read_frame().unwrap();
        let (header, payload) = split_packet(&input_packet);
        assert_eq!(header.packet_type, PacketType::InputEvent);
        input_tx.send(InputEvent::decode(payload).unwrap()).unwrap();
    });

    let temporary = tempfile::tempdir().unwrap();
    let pairing_path = temporary.path().join("pairing-keys.json");
    let config = SessionConfig {
        host: "127.0.0.1".to_owned(),
        tcp_port: tcp_address.port(),
        udp_port,
        client_name: "rust-client".to_owned(),
        capabilities: Capabilities::TEXT_CLIPBOARD_SYNC,
        pairing_store_path: Some(pairing_path.clone()),
        connect_timeout: erd_app::CONNECT_TIMEOUT,
        handshake_ack_timeout: erd_app::HANDSHAKE_ACK_TIMEOUT,
    };
    let session = ClientSession::new(config).unwrap();
    let ready = session.pair_with_pin(pin).unwrap();
    assert_eq!(ready.server.name, "mock-host");
    assert_eq!(session.state().unwrap(), SessionState::Ready);

    let input = InputEvent {
        event_type: InputEventType::KeyDown,
        x: 0.0,
        y: 0.0,
        key_code: 0x00,
        modifiers: Modifiers::COMMAND,
        scroll_dx: 0.0,
        scroll_dy: 0.0,
    };
    session.send_input(input).unwrap();
    assert_eq!(input_rx.recv().unwrap(), input);
    server.join().unwrap();

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        assert_eq!(
            std::fs::metadata(pairing_path)
                .unwrap()
                .permissions()
                .mode()
                & 0o777,
            0o600
        );
    }
}

